package com.gamehub.admin;
import com.gamehub.common.*;import com.gamehub.game.GameService;import com.gamehub.game.dto.GameUpsertRequest;import com.gamehub.game.vo.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/games") public class AdminGameController {private final GameService service;public AdminGameController(GameService service){this.service=service;}@GetMapping public ApiResponse<PageResult<GameCardVO>>list(@RequestParam(defaultValue="1")long page,@RequestParam(defaultValue="20")long size,@RequestParam(required=false)String q,@RequestParam(required=false)Long category,@RequestParam(required=false)String status){return ApiResponse.ok(service.adminList(page,size,q,category,status));}@GetMapping("/{id}")public ApiResponse<GameDetailVO>detail(@PathVariable Long id){return ApiResponse.ok(service.adminDetail(id));}@PostMapping public ApiResponse<GameDetailVO>create(@Valid @RequestBody GameUpsertRequest r){return ApiResponse.ok(service.create(r));}@PutMapping("/{id}")public ApiResponse<GameDetailVO>update(@PathVariable Long id,@Valid @RequestBody GameUpsertRequest r){return ApiResponse.ok(service.update(id,r));}@DeleteMapping("/{id}")public ApiResponse<Void>delete(@PathVariable Long id){service.delete(id);return ApiResponse.ok();}@PostMapping("/{id}/publish")public ApiResponse<Void>publish(@PathVariable Long id){service.publish(id);return ApiResponse.ok();}@PostMapping("/{id}/offline")public ApiResponse<Void>offline(@PathVariable Long id){service.offline(id);return ApiResponse.ok();}}
